body {
  margin: 0;
  font-family: Verdana, sans-serif;
  background-color: #eef2f7;
  color: #1b1e24;
}

/* Celular: tudo numa coluna só */
.site {
  display: grid;
  gap: 12px;
  padding: 12px;
  grid-template-areas:
    "topo"
    "principal"
    "agenda"
    "rodape";
}

.topo {
  grid-area: topo;
}

.principal {
  grid-area: principal;
}

.agenda {
  grid-area: agenda;
}

.rodape {
  grid-area: rodape;
}

.site > * {
  padding: 12px;
  border-radius: 10px;
  background-color: #fff;
}

nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

nav a {
  padding: 8px 12px;
  border-radius: 8px;
  background-color: #0d47a1;
  color: #fff;
  text-decoration: none;
}

